/** Generated by scripts/build-voices.ts when an ElevenLabs credential is configured. */
export const voiceFiles: Record<string,string> = {};
export function voiceKey(speaker:string,text:string):string {let h=2166136261;for(const ch of speaker+'\n'+text){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);}return (h>>>0).toString(16).padStart(8,'0');}
